KG42.register("rules-89ed729d1d55f539a4cdde3e",{"id":"10-hierarchical_coordination::v141-c-R009","paper":"10-hierarchical_coordination","record":{"rule_id":"v141-c-R009","mechanism_id":"v141-a-M02","name":"Local market clearing","process_stage":"clearing","market_meaning":"The LMO coordinates the strategy-one local P2P allocation problem. Scope: First-stage local P2P allocation under coordinating strategy one. Each bilateral allocated P2P sale block is bounded above by the corresponding submitted offer quantity. Scope: Strategy-one local P2P allocation, for each ordered pair of distinct prosumers, block m and time t. Each bilateral allocated P2P purchase block is bounded above by the corresponding submitted bid quantity. Scope: Strategy-one local P2P allocation, for each ordered pair of distinct prosumers, block m and time t. Receipt of submitted offering curves precedes calculation of the local P2P trading quantity. Scope: First-stage local P2P quantity calculation at each time interval, restricted here to coordinating strategy one. Receipt of submitted bidding curves precedes calculation of the local P2P trading quantity. Scope: First-stage local P2P quantity calculation at each time interval, restricted here to coordinating strategy one. Strategy-one allocations minimize the stated sum of offer-price-weighted P2P sale blocks minus bid-price-weighted P2P purchase blocks, subject to Eqs. (16)-(23). Scope: First-stage local P2P allocation under coordinating strategy one. A prosumer's bilateral allocation permits buying or selling, without simultaneous positive allocations in both directions; its sale allocation is bounded by its maximum generation and its purchase allocation by its maximum consumption. Scope: Strategy-one bilateral local P2P allocations between distinct prosumers j and i at each time t. The energy allocated as sold by prosumer j to prosumer i must equal the energy allocated as purchased by prosumer i from prosumer j. Scope: Each bilateral local P2P allocation under coordinating strategy one. Each bilateral total sale or purchase allocation equals the sum of its corresponding allocated P2P energy blocks. Scope: Strategy-one local P2P allocations for each ordered pair of distinct prosumers and time slot.","independence_rationale":"Relations governed by the approved function clearing.local under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["bidding.demand","bidding.supply","clearing.local","coordination.local_operator"],"E":[{"edge_id":"v141-c-R009-E001","source":"bidding.demand","target":"clearing.local","type":"limits","constraint_ids":["v141-c-R009-C003"],"evidence_ids":["v141-b-g02-e18"]},{"edge_id":"v141-c-R009-E002","source":"bidding.demand","target":"clearing.local","type":"precedes","constraint_ids":["v141-c-R009-C005"],"evidence_ids":["v141-b-g02-e34"]},{"edge_id":"v141-c-R009-E003","source":"bidding.supply","target":"clearing.local","type":"limits","constraint_ids":["v141-c-R009-C002"],"evidence_ids":["v141-b-g02-e18"]},{"edge_id":"v141-c-R009-E004","source":"bidding.supply","target":"clearing.local","type":"precedes","constraint_ids":["v141-c-R009-C004"],"evidence_ids":["v141-b-g02-e34"]},{"edge_id":"v141-c-R009-E005","source":"coordination.local_operator","target":"clearing.local","type":"links","constraint_ids":["v141-c-R009-C001"],"evidence_ids":["v141-b-g02-e20","v141-b-g02-e21"]}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"clearing","context_text":"Each bilateral local P2P allocation under coordinating strategy one. | First-stage local P2P allocation under coordinating strategy one. | First-stage local P2P quantity calculation at each time interval, restricted here to coordinating strategy one. | Strategy-one bilateral local P2P allocations between distinct prosumers j and i at each time t. | Strategy-one local P2P allocation, for each ordered pair of distinct prosumers, block m and time t. | Strategy-one local P2P allocations for each ordered pair of distinct prosumers and time slot.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g02-e16","v141-b-g02-e17","v141-b-g02-e18","v141-b-g02-e19","v141-b-g02-e20","v141-b-g02-e21","v141-b-g02-e34"]},"x":[{"variable_id":"v141-c-R009-X-P2P-SEL-BL","symbol":"P^{p2p,+,bl}_{jitm}","meaning":"Allocated P2P sale block: quantity of offering for P2P trading among prosumers j and i at time slot t and block m. Source nomenclature: 'The quantity of offering for P2P trading among prosumers j and i at time slot t and block m'. Decision variable of the strategy-one LMO clearing problem.","kind":"operational","domain":"non-negative real: P^{p2p,+,bl}_{jitm} \\in \\mathbb{R}_{\\ge 0}","unit":"kWh","indices":["j","i","t","m"],"evidence_ids":["v141-b-g02-e18","v141-b-g02-e19","v141-b-g02-e20","v141-b-g01-e18","v141-b-g01-e19","v141-b-g01-e20"]},{"variable_id":"v141-c-R009-X-P2P-BUY-BL","symbol":"P^{p2p,-,bl}_{jitm}","meaning":"Allocated P2P purchase block: quantity of bidding for P2P trading among prosumers j and i at time slot t and block m. Source nomenclature: 'The quantity of bidding for P2P trading among prosumers j and i at time slot t and block m'. Decision variable of the strategy-one LMO clearing problem.","kind":"operational","domain":"non-negative real: P^{p2p,-,bl}_{jitm} \\in \\mathbb{R}_{\\ge 0}","unit":"kWh","indices":["j","i","t","m"],"evidence_ids":["v141-b-g02-e18","v141-b-g02-e19","v141-b-g02-e20","v141-b-g01-e18","v141-b-g01-e19","v141-b-g01-e20"]},{"variable_id":"v141-c-R009-X-P2P-SEL","symbol":"P^{p2p,+}_{jit}","meaning":"Energy that prosumer j sells to prosumer i at time slot t (total bilateral sale, related to the allocated sale blocks by source Eq. 22).","kind":"operational","domain":"non-negative real: P^{p2p,+}_{jit} \\in \\mathbb{R}_{\\ge 0}","unit":"kWh","indices":["j","i","t"],"evidence_ids":["v141-b-g02-e16","v141-b-g02-e17","v141-b-g02-e19","v141-b-g01-e16","v141-b-g01-e17","v141-b-g01-e19"]},{"variable_id":"v141-c-R009-X-P2P-BUY","symbol":"P^{p2p,-}_{jit}","meaning":"Energy that prosumer j buys from prosumer i at time slot t (total bilateral purchase, related to the allocated purchase blocks by source Eq. 23).","kind":"operational","domain":"non-negative real: P^{p2p,-}_{jit} \\in \\mathbb{R}_{\\ge 0}","unit":"kWh","indices":["j","i","t"],"evidence_ids":["v141-b-g02-e16","v141-b-g02-e17","v141-b-g02-e19","v141-b-g01-e16","v141-b-g01-e17","v141-b-g01-e19"]},{"variable_id":"v141-c-R009-X-U","symbol":"u_{jit}","meaning":"Binary variable representing P2P trading status between prosumers j and i at time t; u_{jit}=1 if prosumer j sold energy to prosumer i (source statement accompanying Eqs. 17-18).","kind":"operational","domain":"binary: u_{jit} \\in \\{0,1\\}","unit":null,"indices":["j","i","t"],"evidence_ids":["v141-b-g02-e16","v141-b-g01-e16"]},{"variable_id":"v141-c-R009-X-P2P-NET","symbol":"P^{p2p}_{jit}","meaning":"Net P2P traded energy by prosumer j with prosumer i at time slot t, defined as the sold energy minus the purchased energy (source Eq. 16).","kind":"operational","domain":"real: P^{p2p}_{jit} \\in \\mathbb{R}","unit":"kWh","indices":["j","i","t"],"evidence_ids":["v141-b-g01-e15","v141-b-g02-e15"]}],"theta":[{"parameter_id":"v141-c-R009-T-O","symbol":"O_{jtm}","meaning":"Offering quantity of prosumer j in block m and time t; the submitted offer-block quantity that bounds the allocated P2P sale block (source Eq. 20) and is a fixed input to the LMO clearing problem.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"kWh","indices":["j","t","m"],"evidence_ids":["v141-b-g02-e18","v141-b-g01-e18"]},{"parameter_id":"v141-c-R009-T-B","symbol":"B_{jtm}","meaning":"Bidding quantity of prosumer j in block m and time t; the submitted bid-block quantity that bounds the allocated P2P purchase block (source Eq. 21) and is a fixed input to the LMO clearing problem.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"kWh","indices":["j","t","m"],"evidence_ids":["v141-b-g02-e18","v141-b-g01-e18"]},{"parameter_id":"v141-c-R009-T-LAM-O","symbol":"\\lambda^{o}_{jtm}","meaning":"Offering price of prosumer j in block m and time t; per the source it is an output of the prosumer bidding-strategy problem and therefore a fixed input to the strategy-one clearing objective (Eq. 24).","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["j","t","m"],"evidence_ids":["v141-b-g02-e20","v141-b-g01-e20"]},{"parameter_id":"v141-c-R009-T-LAM-B","symbol":"\\lambda^{b}_{itm}","meaning":"Bidding price in block m and time t, indexed in source Eq. (24) by the counterparty i; an output of the prosumer bidding-strategy problem and therefore a fixed input to the strategy-one clearing objective.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["i","t","m"],"evidence_ids":["v141-b-g02-e20","v141-b-g01-e20"]},{"parameter_id":"v141-c-R009-T-PBAR","symbol":"\\bar{P}_{j}","meaning":"Maximum energy generation (PV capacity) for prosumer j; bounds the bilateral sale allocation in source Eq. (17).","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"kWh","indices":["j"],"evidence_ids":["v141-b-g02-e16","v141-b-g01-e16"]},{"parameter_id":"v141-c-R009-T-LBAR","symbol":"\\bar{L}_{j}","meaning":"Maximum energy consumption for prosumer j; bounds the bilateral purchase allocation in source Eq. (18).","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"kWh","indices":["j"],"evidence_ids":["v141-b-g02-e16","v141-b-g01-e16"]}],"phi":[{"constraint_id":"v141-c-R009-C001","kind":"procedural","role":"core","statement":"The LMO coordinates the strategy-one local P2P allocation problem. Scope: First-stage local P2P allocation under coordinating strategy one.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.local_operator","clearing.local"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-e20","v141-b-g02-e21","v141-b-g01-e20","v141-b-g01-e21"]},{"constraint_id":"v141-c-R009-C002","kind":"mathematical","role":"core","statement":"Each bilateral allocated P2P sale block is bounded above by the corresponding submitted offer quantity. Scope: Strategy-one local P2P allocation, for each ordered pair of distinct prosumers, block m and time t.","expression":"0 \\leq P^{p2p,+,bl}_{jitm} \\leq O_{jtm}, \\; \\forall j, j \\neq i, \\forall m, \\forall t","formalization_origin":"source","template_id":null,"members":["bidding.supply","clearing.local"],"variable_refs":["v141-c-R009-X-P2P-SEL-BL"],"parameter_refs":["v141-c-R009-T-O"],"evidence_ids":["v141-b-g02-e18","v141-b-g01-e18"]},{"constraint_id":"v141-c-R009-C003","kind":"mathematical","role":"core","statement":"Each bilateral allocated P2P purchase block is bounded above by the corresponding submitted bid quantity. Scope: Strategy-one local P2P allocation, for each ordered pair of distinct prosumers, block m and time t.","expression":"0 \\leq P^{p2p,-,bl}_{jitm} \\leq B_{jtm}, \\; \\forall j, j \\neq i, \\forall m, \\forall t","formalization_origin":"source","template_id":null,"members":["bidding.demand","clearing.local"],"variable_refs":["v141-c-R009-X-P2P-BUY-BL"],"parameter_refs":["v141-c-R009-T-B"],"evidence_ids":["v141-b-g02-e18","v141-b-g01-e18"]},{"constraint_id":"v141-c-R009-C004","kind":"procedural","role":"core","statement":"Receipt of submitted offering curves precedes calculation of the local P2P trading quantity. Scope: First-stage local P2P quantity calculation at each time interval, restricted here to coordinating strategy one.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.supply","clearing.local"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-e34"]},{"constraint_id":"v141-c-R009-C005","kind":"procedural","role":"core","statement":"Receipt of submitted bidding curves precedes calculation of the local P2P trading quantity. Scope: First-stage local P2P quantity calculation at each time interval, restricted here to coordinating strategy one.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.demand","clearing.local"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-e34"]},{"constraint_id":"v141-c-R009-C006","kind":"mathematical","role":"core","statement":"Strategy-one allocations minimize the stated sum of offer-price-weighted P2P sale blocks minus bid-price-weighted P2P purchase blocks, subject to Eqs. (16)-(23). Scope: First-stage local P2P allocation under coordinating strategy one.","expression":"OF^{1} = \\sum_{jtm} \\sum_{i(i \\neq j)} \\left( \\lambda^{o}_{jtm} P^{p2p,+,bl}_{jitm} - \\lambda^{b}_{itm} P^{p2p,-,bl}_{jitm} \\right); \\quad \\min OF^{1} \\quad \\text{s.t. } (16)\\text{--}(23)","formalization_origin":"source","template_id":null,"members":["clearing.local"],"variable_refs":["v141-c-R009-X-P2P-SEL-BL","v141-c-R009-X-P2P-BUY-BL"],"parameter_refs":["v141-c-R009-T-LAM-O","v141-c-R009-T-LAM-B"],"evidence_ids":["v141-b-g02-e20","v141-b-g02-e21","v141-b-g01-e20","v141-b-g01-e21"]},{"constraint_id":"v141-c-R009-C007","kind":"mathematical","role":"core","statement":"A prosumer's bilateral allocation permits buying or selling, without simultaneous positive allocations in both directions; its sale allocation is bounded by its maximum generation and its purchase allocation by its maximum consumption. Scope: Strategy-one bilateral local P2P allocations between distinct prosumers j and i at each time t.","expression":"0 \\leq P^{p2p,+}_{jit} \\leq \\bar{P}_{j} u_{jit}, \\; \\forall j, j \\neq i, \\forall t; \\quad 0 \\leq P^{p2p,-}_{jit} \\leq \\bar{L}_{j} (1 - u_{jit}), \\; \\forall j, j \\neq i, \\forall t","formalization_origin":"source","template_id":null,"members":["clearing.local"],"variable_refs":["v141-c-R009-X-P2P-SEL","v141-c-R009-X-P2P-BUY","v141-c-R009-X-U"],"parameter_refs":["v141-c-R009-T-PBAR","v141-c-R009-T-LBAR"],"evidence_ids":["v141-b-g02-e16","v141-b-g01-e16"]},{"constraint_id":"v141-c-R009-C008","kind":"mathematical","role":"core","statement":"The energy allocated as sold by prosumer j to prosumer i must equal the energy allocated as purchased by prosumer i from prosumer j. Scope: Each bilateral local P2P allocation under coordinating strategy one.","expression":"P^{p2p,+}_{jit} - P^{p2p,-}_{ijt} = 0, \\; \\forall j, j \\neq i, \\forall t","formalization_origin":"source","template_id":null,"members":["clearing.local"],"variable_refs":["v141-c-R009-X-P2P-SEL","v141-c-R009-X-P2P-BUY"],"parameter_refs":[],"evidence_ids":["v141-b-g02-e17","v141-b-g01-e17"]},{"constraint_id":"v141-c-R009-C009","kind":"mathematical","role":"core","statement":"Each bilateral total sale or purchase allocation equals the sum of its corresponding allocated P2P energy blocks. Scope: Strategy-one local P2P allocations for each ordered pair of distinct prosumers and time slot.","expression":"P^{p2p,+}_{jit} = \\sum_{m} P^{p2p,+,bl}_{jitm}, \\; \\forall j, j \\neq i, \\forall t; \\quad P^{p2p,-}_{jit} = \\sum_{m} P^{p2p,-,bl}_{jitm}, \\; \\forall j, j \\neq i, \\forall t","formalization_origin":"source","template_id":null,"members":["clearing.local"],"variable_refs":["v141-c-R009-X-P2P-SEL","v141-c-R009-X-P2P-BUY","v141-c-R009-X-P2P-SEL-BL","v141-c-R009-X-P2P-BUY-BL"],"parameter_refs":[],"evidence_ids":["v141-b-g02-e19","v141-b-g01-e19"]},{"constraint_id":"v141-c-R009-C010","kind":"mathematical","role":"supporting","statement":"The net bilateral P2P traded energy of prosumer j with prosumer i at time t equals its allocated sale minus its allocated purchase. Scope: Each bilateral local P2P allocation under coordinating strategy one (source Eq. 16); part of the constraint set (16)-(23) referenced by C006.","expression":"P^{p2p}_{jit} = P^{p2p,+}_{jit} - P^{p2p,-}_{jit}, \\; \\forall j, j \\neq i, \\forall t","formalization_origin":"source","template_id":null,"members":["clearing.local"],"variable_refs":["v141-c-R009-X-P2P-NET","v141-c-R009-X-P2P-SEL","v141-c-R009-X-P2P-BUY"],"parameter_refs":[],"evidence_ids":["v141-b-g01-e15","v141-b-g02-e15"]}],"pi":[{"evidence_id":"v141-b-g02-e16","location":{"location_id":"src-87ebdce2a6-p05-c1r3__v141-a-M02-matching","page":5,"printed_page":null,"section":"2.1.2. P2P coordinating problem","anchor_text":"at time 𝑡. Besides, 𝑂𝑗𝑡𝑚and 𝜆𝑗𝑡𝑚state offering quantity and price of prosumer 𝑗in block 𝑚and time 𝑡,","equation_id":"(17)-(18)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"condition"},"source_text":"Moreover, prosumer j can only buy or sell energy from prosumer i at time t as stated in Eqs. (17) and (18): 0 \\leq P^{p2p,+}_{jit} \\leq \\bar{P}_{j} u_{jit}, \\forall j, j \\neq i, \\forall t   (17)   0 \\leq P^{p2p,-}_{jit} \\leq \\bar{L}_{j} (1 - u_{jit}), \\forall j, j \\neq i, \\forall t   (18) where \\bar{P}_{j} and \\bar{L}_{j} represent maximum energy generation (PV capacity) and consumption for prosumer j. Besides, u_{jit} is a binary variable representing P2P trading status between prosumers j and i at time t, such that u_{jit} = 1 if prosumer j sold energy to prosumer i."},{"evidence_id":"v141-b-g02-e17","location":{"location_id":"src-87ebdce2a6-p05-c1r4__v141-a-M02-clearing","page":5,"printed_page":null,"section":"2.1.2. P2P coordinating problem","anchor_text":"𝑗 where 𝑃𝑗and 𝐿𝑗represent maximum energy generation (PV capacity) and consumption for prosumer 𝑗. Be","equation_id":"(19)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"condition"},"source_text":"The demand supply balance constraint in each trade is modeled in Eq. (19), which implies that the amount of energy sold by prosumer j to i should be equal to the energy that prosumer i purchases from prosumer j: P^{p2p,+}_{jit} - P^{p2p,-}_{ijt} = 0, \\forall j, j \\neq i, \\forall t.   (19)"},{"evidence_id":"v141-b-g02-e18","location":{"location_id":"src-87ebdce2a6-p05-c1r4__v141-a-M02-clearing","page":5,"printed_page":null,"section":"2.1.2. P2P coordinating problem","anchor_text":"𝑗 where 𝑃𝑗and 𝐿𝑗represent maximum energy generation (PV capacity) and consumption for prosumer 𝑗. Be","equation_id":"(20)-(21)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"condition"},"source_text":"Eqs. (20) and (21) represent maximum and minimum constraints of P2P energy blocks: 0 \\leq P^{p2p,+,bl}_{jitm} \\leq O_{jtm}, \\forall j, j \\neq i, \\forall m, \\forall t   (20)   0 \\leq P^{p2p,-,bl}_{jitm} \\leq B_{jtm}, \\forall j, j \\neq i, \\forall m, \\forall t   (21)"},{"evidence_id":"v141-b-g02-e19","location":{"location_id":"src-87ebdce2a6-p05-c2r1__v141-a-M02-clearing","page":5,"printed_page":null,"section":"2.1.2. P2P coordinating problem","anchor_text":"Applied Energy 302 (2021) 117575 to where 𝑃𝑝2𝑝,+,𝑏𝑙𝑗𝑖𝑡𝑚 and 𝑃𝑝2𝑝,−,𝑏𝑙𝑗𝑖𝑡, express the quantity of of","equation_id":"(22)-(23)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"Besides, the relation between total P2P energy traded among prosumers j and i and the P2P energy blocks are represented in Eqs. (22) and (23): P^{p2p,+}_{jit} = \\sum_{m} P^{p2p,+,bl}_{jitm}, \\forall j, j \\neq i, \\forall t.   (22)   P^{p2p,-}_{jit} = \\sum_{m} P^{p2p,-,bl}_{jitm}, \\forall j, j \\neq i, \\forall t.   (23)"},{"evidence_id":"v141-b-g02-e20","location":{"location_id":"src-87ebdce2a6-p05-c2r1__v141-a-M02-clearing","page":5,"printed_page":null,"section":"2.1.2. P2P coordinating problem","anchor_text":"Applied Energy 302 (2021) 117575 to where 𝑃𝑝2𝑝,+,𝑏𝑙𝑗𝑖𝑡𝑚 and 𝑃𝑝2𝑝,−,𝑏𝑙𝑗𝑖𝑡, express the quantity of of","equation_id":"(24)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"In this paper, we propose two coordinating strategies for P2P energy trading in the LEM. In strategy one, \\Upsilon^{1}, the LMO coordinates the P2P energy transactions locally to maximize matching the offering and bidding blocks submitted by prosumers as presented in (24): OF^{1} = \\sum_{jtm} \\sum_{i(i \\neq j)} (\\lambda^{o}_{jtm} P^{p2p,+,bl}_{jitm} - \\lambda^{b}_{itm} P^{p2p,-,bl}_{jitm}),   (24) where \\lambda^{o}_{jtm} and \\lambda^{b}_{itm} present offering and bidding prices for P2P trading between prosumers j and i at time t and block m which are outputs of bidding strategy problem for prosumer j. Moreover, it is noted that \\lambda^{o}_{jtm} (\\lambda^{b}_{jtm}) are different with \\lambda^{lm}_{jt\\omega} which is an input of bidding strategy problem for prosumer j."},{"evidence_id":"v141-b-g02-e21","location":{"location_id":"src-87ebdce2a6-p05-c2r2__v141-a-M02-clearing","page":5,"printed_page":null,"section":"2.1.2. P2P coordinating problem","anchor_text":"P2P energy transactions locally to maximize matching the offering and In bidding blocks submitted by","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"In this way, the decision-making problem of the LMO for coordinating P2P energy trading based on strategy one is given: min OF^{1}  s.t. : (16)-(23)."},{"evidence_id":"v141-b-g02-e34","location":{"location_id":"src-87ebdce2a6-p07-c1r4__v141-a-M02-matching","page":7,"printed_page":null,"section":"3.2. Evaluation of P2P coordinating strategies","anchor_text":"pr in calculated using Eqs. (4)–(13). Then, each prosumer submits its offering th and bidding curves","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-07.png","occurrence_role":"restatement"},"source_text":"Then, each prosumer submits its offering and bidding curves at each time interval to the LMO. In other words, each prosumer is able to play as a seller or a buyer at each time snapshot in the local market and submits either its corresponding offering or bidding curves to the LMO. After receiving offering and bidding curves, the P2P energy trading quantity will be calculated using either strategy one or two according to Eqs. (16)-(23)."},{"evidence_id":"v141-b-g01-e15","location":{"location_id":"src-87ebdce2a6-p05-c1r3__v141-a-M02-matching","page":5,"printed_page":"5","section":"2.1.2. P2P coordinating problem","anchor_text":"at time 𝑡. Besides, 𝑂𝑗𝑡𝑚and 𝜆𝑗𝑡𝑚state offering quantity and price of prosumer 𝑗in block 𝑚and time 𝑡,","equation_id":"(16)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"P^{p2p}_{jit} = P^{p2p,+}_{jit} - P^{p2p,-}_{jit}, \\forall j, j \\neq i, \\forall t \\qquad (16)"},{"evidence_id":"v141-b-g01-e16","location":{"location_id":"src-87ebdce2a6-p05-c1r3__v141-a-M02-matching","page":5,"printed_page":"5","section":"2.1.2. P2P coordinating problem","anchor_text":"at time 𝑡. Besides, 𝑂𝑗𝑡𝑚and 𝜆𝑗𝑡𝑚state offering quantity and price of prosumer 𝑗in block 𝑚and time 𝑡,","equation_id":"(17),(18)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"condition"},"source_text":"0 \\leq P^{p2p,+}_{jit} \\leq \\bar{P}_{j} u_{jit}, \\forall j, j \\neq i, \\forall t \\qquad (17)\n0 \\leq P^{p2p,-}_{jit} \\leq \\bar{L}_{j}(1 - u_{jit}), \\forall j, j \\neq i, \\forall t \\qquad (18)"},{"evidence_id":"v141-b-g01-e17","location":{"location_id":"src-87ebdce2a6-p05-c1r4__v141-a-M02-clearing","page":5,"printed_page":"5","section":"2.1.2. P2P coordinating problem","anchor_text":"𝑗 where 𝑃𝑗and 𝐿𝑗represent maximum energy generation (PV capacity) and consumption for prosumer 𝑗. Be","equation_id":"(19)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"condition"},"source_text":"P^{p2p,+}_{jit} - P^{p2p,-}_{ijt} = 0, \\forall j, j \\neq i, \\forall t. \\qquad (19)"},{"evidence_id":"v141-b-g01-e18","location":{"location_id":"src-87ebdce2a6-p05-c1r4__v141-a-M02-clearing","page":5,"printed_page":"5","section":"2.1.2. P2P coordinating problem","anchor_text":"𝑗 where 𝑃𝑗and 𝐿𝑗represent maximum energy generation (PV capacity) and consumption for prosumer 𝑗. Be","equation_id":"(20),(21)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"condition"},"source_text":"0 \\leq P^{p2p,+,bl}_{jitm} \\leq O_{jtm}, \\forall j, j \\neq i, \\forall m, \\forall t \\qquad (20)\n0 \\leq P^{p2p,-,bl}_{jitm} \\leq B_{jtm}, \\forall j, j \\neq i, \\forall m, \\forall t \\qquad (21)"},{"evidence_id":"v141-b-g01-e19","location":{"location_id":"src-87ebdce2a6-p05-c2r1__v141-a-M02-clearing","page":5,"printed_page":"5","section":"2.1.2. P2P coordinating problem","anchor_text":"Applied Energy 302 (2021) 117575 to where 𝑃𝑝2𝑝,+,𝑏𝑙𝑗𝑖𝑡𝑚 and 𝑃𝑝2𝑝,−,𝑏𝑙𝑗𝑖𝑡, express the quantity of of","equation_id":"(22),(23)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"P^{p2p,+}_{jit} = \\sum_{m} P^{p2p,+,bl}_{jitm}, \\forall j, j \\neq i, \\forall t. \\qquad (22)\nP^{p2p,-}_{jit} = \\sum_{m} P^{p2p,-,bl}_{jitm}, \\forall j, j \\neq i, \\forall t. \\qquad (23)"},{"evidence_id":"v141-b-g01-e20","location":{"location_id":"src-87ebdce2a6-p05-c2r1__v141-a-M02-clearing","page":5,"printed_page":"5","section":"2.1.2. P2P coordinating problem","anchor_text":"Applied Energy 302 (2021) 117575 to where 𝑃𝑝2𝑝,+,𝑏𝑙𝑗𝑖𝑡𝑚 and 𝑃𝑝2𝑝,−,𝑏𝑙𝑗𝑖𝑡, express the quantity of of","equation_id":"(24)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"OF^{1} = \\sum_{jtm} \\sum_{i(i \\neq j)} (\\lambda^{o}_{jtm} P^{p2p,+,bl}_{jitm} - \\lambda^{b}_{itm} P^{p2p,-,bl}_{jitm}), \\qquad (24)"},{"evidence_id":"v141-b-g01-e21","location":{"location_id":"src-87ebdce2a6-p05-c2r2__v141-a-M02-clearing","page":5,"printed_page":"5","section":"2.1.2. P2P coordinating problem","anchor_text":"P2P energy transactions locally to maximize matching the offering and In bidding blocks submitted by","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"min OF^{1}\ns.t. : (16)-(23)."},{"evidence_id":"v141-b-g02-e15","location":{"location_id":"src-87ebdce2a6-p05-c1r3__v141-a-M02-matching","page":5,"printed_page":null,"section":"2.1.2. P2P coordinating problem","anchor_text":"at time 𝑡. Besides, 𝑂𝑗𝑡𝑚and 𝜆𝑗𝑡𝑚state offering quantity and price of prosumer 𝑗in block 𝑚and time 𝑡,","equation_id":"(16)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"In this way, total P2P traded energy by prosumer j with prosumer i is split into P2P sold energy and P2P purchased as represented in Eq. (16): P^{p2p}_{jit} = P^{p2p,+}_{jit} - P^{p2p,-}_{jit}, \\forall j, j \\neq i, \\forall t   (16) where P^{p2p,+}_{jit} (P^{p2p,-}_{jit}) presents energy that prosumer j sells (buys) to (from) prosumer i at time t."}],"field_notes":{"empty_E_reason":null,"empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-bidding","v141-a-M02-clearing","v141-a-M02-matching","v141-a-M03-clearing","v141-a-M03-matching"],"extras":{"decision_anchor":"clearing.local","graph_fact_supports":[[{"evidence_id":"v141-b-g02-e21","quote":"In this way, the decision-making problem of the LMO for coordinating P2P energy trading based on strategy one is given: min OF^{1}  s.t. : (16)-(23)."},{"evidence_id":"v141-b-g02-e20","quote":"the LMO coordinates the P2P energy transactions locally to maximize matching the offering and bidding blocks submitted by prosumers"}],[{"evidence_id":"v141-b-g02-e18","quote":"Eqs. (20) and (21) represent maximum and minimum constraints of P2P energy blocks: 0 \\leq P^{p2p,+,bl}_{jitm} \\leq O_{jtm}, \\forall j, j \\neq i, \\forall m, \\forall t   (20)"}],[{"evidence_id":"v141-b-g02-e18","quote":"0 \\leq P^{p2p,-,bl}_{jitm} \\leq B_{jtm}, \\forall j, j \\neq i, \\forall m, \\forall t   (21)"}],[{"evidence_id":"v141-b-g02-e34","quote":"After receiving offering and bidding curves, the P2P energy trading quantity will be calculated using either strategy one or two according to Eqs. (16)-(23)."}],[{"evidence_id":"v141-b-g02-e34","quote":"After receiving offering and bidding curves, the P2P energy trading quantity will be calculated using either strategy one or two according to Eqs. (16)-(23)."}],[{"evidence_id":"v141-b-g02-e20","quote":"OF^{1} = \\sum_{jtm} \\sum_{i(i \\neq j)} (\\lambda^{o}_{jtm} P^{p2p,+,bl}_{jitm} - \\lambda^{b}_{itm} P^{p2p,-,bl}_{jitm}),   (24)"},{"evidence_id":"v141-b-g02-e21","quote":"min OF^{1}  s.t. : (16)-(23)."}],[{"evidence_id":"v141-b-g02-e16","quote":"Moreover, prosumer j can only buy or sell energy from prosumer i at time t as stated in Eqs. (17) and (18): 0 \\leq P^{p2p,+}_{jit} \\leq \\bar{P}_{j} u_{jit}, \\forall j, j \\neq i, \\forall t   (17)   0 \\leq P^{p2p,-}_{jit} \\leq \\bar{L}_{j} (1 - u_{jit}), \\forall j, j \\neq i, \\forall t   (18) where \\bar{P}_{j} and \\bar{L}_{j} represent maximum energy generation (PV capacity) and consumption for prosumer j."}],[{"evidence_id":"v141-b-g02-e17","quote":"The demand supply balance constraint in each trade is modeled in Eq. (19), which implies that the amount of energy sold by prosumer j to i should be equal to the energy that prosumer i purchases from prosumer j"}],[{"evidence_id":"v141-b-g02-e19","quote":"P^{p2p,+}_{jit} = \\sum_{m} P^{p2p,+,bl}_{jitm}, \\forall j, j \\neq i, \\forall t.   (22)   P^{p2p,-}_{jit} = \\sum_{m} P^{p2p,-,bl}_{jitm}, \\forall j, j \\neq i, \\forall t.   (23)"}]],"C2_formalization":{"graph_sha256":"8a5865f047407fcad55096852569238a1b7f2bab909bd941606cc68ee7e9d2f2","applicability":"formalized","reason":"Rule v141-c-R009 is the strategy-one local P2P clearing (LMO allocation) problem, a mixed-integer linear programme whose decision quantities are the per-block P2P allocations, the induced bilateral sale/purchase totals and the binary trading-status variable. Six existing constraints (C002, C003, C006, C007, C008, C009) are transcribed with formalization_origin=source directly from the supplied B source_text (Eqs. (17)-(18), (20)-(21), (22)-(23), (24) and the min-problem statement), and one source-supported constraint (C010, Eq. (16)) is added with existing members. C001, C004 and C005 remain procedural ownership/ordering statements with no faithful closed-form expression (expression=null, not_formalized). The submitted offer/bid quantities and prices, the PV capacity and the maximum consumption enter the clearing problem as fixed inputs (theta), because the source states the offer/bid quantities and prices are submitted by prosumers and are outputs of the earlier bidding-strategy problem. All B evidence supplied for this rule is UNREVIEWED in this experiment (audit_performed=false); every formalization here is therefore provisional candidate support and does not claim that B transcription or downstream science has passed independent source review.","bindings":[{"object_id":"v141-c-R009-X-P2P-SEL-BL","node_ids":["clearing.local"],"edge_ids":["v141-c-R009-E003"],"rationale":"The per-block sale allocation is a decision quantity of the clearing node; its upper bound comes from the submitted offer, which the C.1 edge E003 (bidding.supply limits clearing.local, constraint C002) encodes."},{"object_id":"v141-c-R009-X-P2P-BUY-BL","node_ids":["clearing.local"],"edge_ids":["v141-c-R009-E001"],"rationale":"The per-block purchase allocation is a decision quantity of the clearing node; its upper bound comes from the submitted bid, encoded by C.1 edge E001 (bidding.demand limits clearing.local, constraint C003)."},{"object_id":"v141-c-R009-X-P2P-SEL","node_ids":["clearing.local"],"edge_ids":["v141-c-R009-E003"],"rationale":"Bilateral sale total determined inside clearing.local (Eq. 22) and bounded through the supply-side link E003."},{"object_id":"v141-c-R009-X-P2P-BUY","node_ids":["clearing.local"],"edge_ids":["v141-c-R009-E001"],"rationale":"Bilateral purchase total determined inside clearing.local (Eq. 23) and bounded through the demand-side link E001."},{"object_id":"v141-c-R009-X-U","node_ids":["clearing.local"],"edge_ids":[],"rationale":"Binary trading-status variable appears in the clearing constraints (Eqs. 17-18) that belong to clearing.local; no graph edge specifically encodes this binary selection."},{"object_id":"v141-c-R009-X-P2P-NET","node_ids":["clearing.local"],"edge_ids":[],"rationale":"Net bilateral position defined by Eq. (16) within the clearing constraint set; it is an accounting relation on clearing.local quantities, not a graph relation."},{"object_id":"v141-c-R009-T-O","node_ids":["bidding.supply","clearing.local"],"edge_ids":["v141-c-R009-E003"],"rationale":"Submitted offer quantity flows from bidding.supply into clearing.local and limits the sale block via edge E003 (constraint C002)."},{"object_id":"v141-c-R009-T-B","node_ids":["bidding.demand","clearing.local"],"edge_ids":["v141-c-R009-E001"],"rationale":"Submitted bid quantity flows from bidding.demand into clearing.local and limits the purchase block via edge E001 (constraint C003)."},{"object_id":"v141-c-R009-T-LAM-O","node_ids":["bidding.supply","clearing.local"],"edge_ids":["v141-c-R009-E004"],"rationale":"Offering price is an output of the prosumer bidding stage submitted to the LMO; the C.1 edge E004 (bidding.supply precedes clearing.local, constraint C004) captures the ordering by which this input reaches the clearing objective."},{"object_id":"v141-c-R009-T-LAM-B","node_ids":["bidding.demand","clearing.local"],"edge_ids":["v141-c-R009-E002"],"rationale":"Bidding price is an output of the prosumer bidding stage submitted to the LMO; the C.1 edge E002 (bidding.demand precedes clearing.local, constraint C005) captures the ordering by which this input reaches the clearing objective."},{"object_id":"v141-c-R009-T-PBAR","node_ids":["clearing.local"],"edge_ids":[],"rationale":"PV capacity is a fixed prosumer parameter bounding the sale allocation in Eq. (17) inside the clearing problem; the frozen graph has no separate resource node for it."},{"object_id":"v141-c-R009-T-LBAR","node_ids":["clearing.local"],"edge_ids":[],"rationale":"Maximum consumption is a fixed prosumer parameter bounding the purchase allocation in Eq. (18) inside the clearing problem; the frozen graph has no separate resource node for it."},{"object_id":"v141-c-R009-C001","node_ids":["coordination.local_operator","clearing.local"],"edge_ids":["v141-c-R009-E005"],"rationale":"Ownership/coordination statement, expressed by C.1 edge E005 (coordination.local_operator links clearing.local)."},{"object_id":"v141-c-R009-C002","node_ids":["bidding.supply","clearing.local"],"edge_ids":["v141-c-R009-E003"],"rationale":"Offer-block upper bound on the allocated sale block; grounded on edge E003 (bidding.supply limits clearing.local)."},{"object_id":"v141-c-R009-C003","node_ids":["bidding.demand","clearing.local"],"edge_ids":["v141-c-R009-E001"],"rationale":"Bid-block upper bound on the allocated purchase block; grounded on edge E001 (bidding.demand limits clearing.local)."},{"object_id":"v141-c-R009-C004","node_ids":["bidding.supply","clearing.local"],"edge_ids":["v141-c-R009-E004"],"rationale":"Precedence of offer submission before clearing; grounded on edge E004 (bidding.supply precedes clearing.local)."},{"object_id":"v141-c-R009-C005","node_ids":["bidding.demand","clearing.local"],"edge_ids":["v141-c-R009-E002"],"rationale":"Precedence of bid submission before clearing; grounded on edge E002 (bidding.demand precedes clearing.local)."},{"object_id":"v141-c-R009-C006","node_ids":["clearing.local"],"edge_ids":["v141-c-R009-E005"],"rationale":"Strategy-one objective and min-problem are the clearing decision problem itself; the LMO's coordination role over it is captured by edge E005."},{"object_id":"v141-c-R009-C007","node_ids":["clearing.local"],"edge_ids":[],"rationale":"Directional exclusivity and generation/consumption bounds on the bilateral allocations are constraints of the clearing problem; no dedicated C.1 edge models them."},{"object_id":"v141-c-R009-C008","node_ids":["clearing.local"],"edge_ids":[],"rationale":"Per-trade demand-supply balance between the two counterparties is a clearing constraint on clearing.local quantities."},{"object_id":"v141-c-R009-C009","node_ids":["clearing.local"],"edge_ids":[],"rationale":"Block aggregation into the bilateral totals is a definitional clearing relation on clearing.local."},{"object_id":"v141-c-R009-C010","node_ids":["clearing.local"],"edge_ids":[],"rationale":"Net bilateral position definition belongs to the clearing constraint set (16)-(23); it relates clearing.local quantities only."}],"revision_requests":["Non-blocking clarification: Eq. (24) prints the second-term price as \\lambda^{b}_{itm} (counterparty index i) although the surrounding text speaks of prosumer j's bidding price; the B evidence interpretation itself flags this subscript ambiguity. It is transcribed exactly as printed; source re-extraction/verification is needed if a corrected index was intended.","Non-blocking clarification: Eq. (19) prints P^{p2p,-}_{ijt} with indices swapped relative to the j,i convention used elsewhere in Eqs. (16)-(23); transcribed faithfully as printed.","Reminder (experimental policy): all B evidence attached to this rule is UNREVIEWED (audit_performed=false). These formalizations are provisional candidate support only and do not assert verified source correctness."]}},"quarantined_references":[]}});
